def ones_complement(binary_number):
    """
    Calculates the Ones' Complement of a binary number.

    Args:
        binary_number: A string representing a binary number.

    Returns:
        A string representing the Ones' Complement of the input binary number.
    """
    complement = []
    for bit in binary_number:
        if bit == '0':
            complement.append('1')
        elif bit == '1':
            complement.append('0')
        else:
            # Handle invalid characters if necessary, or assume valid input
            raise ValueError("Input must be a binary string containing only '0' or '1'.")
    return "".join(complement)
